// Riddles pack 5: real riddles only, mostly medium and hard (classic verse retold, wordplay, lateral thinking, and
// "what am I" metaphor riddles), written for the daily riddle's harder days. Same schema as data/riddles.js.
(function (root) { root.RIDDLES_MORE = (root.RIDDLES_MORE || []).concat([
    { id: "p5-shield", d: "hard", q: "I am a lonely fighter, scarred by iron and bitten by blades.\nI go to every battle, yet I have never struck a blow.\nI take the wounds that were meant for my friend,\nand no doctor in the town has a herb that can heal me: my wounds only grow wider.", a: "a shield",
      alt: ["buckler","round shield","wooden shield","kite shield"],
      hints: ["I am not a warrior. I am something a warrior carries.","I hang on his arm and stand between him and the blows."],
      why: "A shield goes into every fight but only ever blocks. The blows meant for the one carrying it land on it instead, and no medicine mends a cut in wood and iron.", from: "The Exeter Book, riddle 5 (retold)" },
    { id: "p5-sword", d: "hard", q: "Fire was my cradle, and a hammer rocked me.\nMy lord dresses me in gold and keeps me close at his side,\nbut at night I lie in a narrow house of leather.\nIf I tap a kneeling man gently on the shoulder, he stands up a knight.", a: "a sword",
      alt: ["broadsword","longsword","long sword","sabre","saber","blade","rapier","cutlass"],
      hints: ["A knight would never ride out without me.","My narrow leather house is called a scabbard."],
      why: "A sword is forged in fire under the hammer, worn at its owner's side and kept in a leather scabbard. A king makes a man a knight by touching his shoulder with the flat of a sword.", from: "The Exeter Book, riddle 20 (retold)" },
    { id: "p5-chainmail", d: "hard", q: "The cold, wet earth was my first mother.\nNo sheep gave me wool and no silkworm spun me,\nand no shuttle ever hummed across me on a loom.\nYet I am a shirt, and I jingle when my wearer walks.\nA warrior is glad of me when the arrows fly.", a: "chain mail",
      alt: ["chainmail","coat of mail","mail coat","mail shirt","armour","armor","suit of armour","suit of armor","body armour","body armor","byrnie","hauberk"],
      hints: ["I was dug up as ore and hammered, not woven.","Knights wore me, made of thousands of little iron rings."],
      why: "Mail is made of iron, which comes out of the earth, so no wool, silk or loom had any part in it. Yet it is worn like a shirt, it jingles as you move, and it turns arrows and blades aside.", from: "The Exeter Book, riddle 35 (retold)" },
    { id: "p5-bow", d: "hard", q: "My two ends are tied together with a cord, so I can never stand up straight.\nWhen my master pulls the cord toward his heart, I bend lower still,\nand then a feathered thing leaps out of me and flies off to bite someone far away.\nUntie me and I am only a stick.", a: "a bow",
      alt: ["longbow","long bow","crossbow","hunting bow","archers bow"],
      hints: ["Robin Hood never went into the forest without me.","The feathered thing that leaps from me is an arrow."],
      why: "A bow is held bent by its string. Draw the string back and it bends further, then the arrow leaps out and flies. Without its string it is just a length of wood.", from: "The Exeter Book, riddle 23 (retold)" },
    { id: "p5-horn", d: "hard", q: "Once I was a weapon on a living head, and I fought for my master in the field.\nNow I am dressed in silver, and the warriors kiss me.\nSometimes I hold their drink at the feast;\nsometimes I call them to the hunt with a voice that carries over the hills.", a: "a horn",
      alt: ["drinking horn","hunting horn","ox horn","bull horn","bulls horn","cow horn","animal horn"],
      hints: ["I first grew on the head of a bull.","You can drink from me, or blow into me."],
      why: "A horn grew on an ox or bull as its weapon. Trimmed with silver, it became a drinking cup at the feast and a horn to blow for the hunt, and drinkers and hunters alike put their lips to it.", from: "The Exeter Book, riddle 14 (retold)" },
    { id: "p5-bellows", d: "hard", q: "I saw a creature with no lungs that breathed harder than any man.\nA strong servant hugged it, and its belly swelled and sank.\nIt swallowed nothing but air,\nand every sigh from its long nose made the fire leap up and roar.", a: "bellows",
      alt: ["bellow","a bellows","pair of bellows","fire bellows","blacksmiths bellows","forge bellows"],
      hints: ["You would find me beside a forge or a fireplace.","Squeeze my two handles together and I puff air at the coals."],
      why: "Bellows have no lungs but blow harder than a person can. Pull the handles apart and the leather belly fills with air; squeeze them and it puffs out through the nozzle, making the fire burn hotter.", from: "The Exeter Book, riddle 37 (retold)" },
    { id: "p5-weathercock", d: "hard", q: "I am a rooster who never crows and never eats.\nI stand on one leg on the highest roof in town, through rain and snow.\nNo farmer feeds me, but every storm turns my head,\nand the farmer looks up at me before he cuts his hay.", a: "a weathercock",
      alt: ["weather cock","weather vane","weathervane","wind vane","vane","weather rooster"],
      hints: ["You will find me on top of a church spire or a barn.","The wind spins me round to point where it is coming from."],
      why: "A weathercock is a metal rooster on a roof. It never crows or eats and stands on a single rod, and the wind turns it to show which way the weather is coming from, which farmers checked before haymaking.", from: "German folk riddle (retold)" },
    { id: "p5-dough", d: "hard", q: "In a warm corner, under a cloth, a creature with no bones is growing.\nIt swells, it rises, and it lifts its blanket all by itself.\nThe woman of the house comes and punches it flat with her fists,\nand without a word of complaint it starts to rise all over again.", a: "dough",
      alt: ["bread dough","dough ball","pizza dough","yeast dough","raw dough","unbaked bread","a lump of dough"],
      hints: ["Yeast is the reason I grow.","I am not bread yet, but I will be after the oven."],
      why: "Bread dough is left somewhere warm under a cloth, and the yeast makes it swell until it lifts the cloth. The baker knocks it back with her fists, and it rises again before it is baked.", from: "The Exeter Book, riddle 45 (retold)" },
    { id: "p5-gold", d: "hard", q: "Slaves dig me out of the dark, and then I rule over kings.\nThrow me in the fire and I melt, but I never burn;\nbeat me as thin as a leaf and I do not tear;\nbury me for a thousand years and I come up shining.\nI cannot feed you or keep you warm, yet men sail round the world to find me.", a: "gold",
      alt: ["gold bar","gold bars","gold nugget","gold nuggets","nugget","bar of gold","gold bullion"],
      hints: ["Pirates bury me in chests.","I am a yellow metal that never rusts."],
      why: "Gold is mined from deep underground but has always ruled kings and kingdoms. It melts without burning, can be hammered into gold leaf, never tarnishes, and explorers crossed oceans hunting for it.", from: "Jonathan Swift, 'On Gold' (retold)" },
    { id: "p5-corkscrew", d: "hard", q: "I live shut up in a kitchen drawer, yet my trade is setting prisoners free.\nI never knock at the door: I worm my way into the guard with a twist, and a twist, and a twist,\nthen haul him out headfirst with a pop,\nand the prisoner pours out of the glass tower to cheers from the table.", a: "a corkscrew",
      alt: ["cork screw","bottle opener","wine opener","cork puller"],
      hints: ["The guard at the door of the glass tower is a cork.","My metal tail is a spiral."],
      why: "A corkscrew lives in a drawer but frees what is shut in a bottle. It twists into the cork, pulls it out with a pop, and the drink can pour at last. Swift wrote a riddle on this idea.", from: "Jonathan Swift, 'On a Corkscrew' (retold)" },
    { id: "p5-counterfeit", d: "hard", q: "The one who makes me keeps very quiet about it.\nThe one who takes me does not know what he has got.\nThe one who knows what I am will not take me.\nI look just like my brothers in your purse, but I am worth nothing at all.", a: "counterfeit money",
      alt: ["counterfeit","counterfeit coin","counterfeit coins","counterfeit note","counterfeit cash","fake money","fake coin","fake coins","fake note","fake cash","fake banknote","forged money","forged coin","forged note","forgery","false coin","funny money","+counterfeit","+fake money","+forged money"],
      hints: ["I am in a purse, but you would not want me there.","A crook made me in his cellar to fool the shops."],
      why: "A forger keeps quiet about the fake money he makes; whoever is handed it does not know it is fake; and anyone who can tell would never accept it. It looks like real money but is worth nothing.", from: "German folk riddle (retold)" },
    { id: "p5-mule", d: "hard", q: "My mother does not look like me, and neither does my father,\nfor they were two different kinds of creature.\nI was born of others, but no one will ever be born of me.\nI have my father's long ears and my mother's strong back, and I will carry your load up any mountain.", a: "a mule",
      alt: [],
      hints: ["My father is a donkey.","My mother is a horse."],
      why: "A mule is the foal of a donkey father and a horse mother, so it looks like neither. Mules almost never have foals of their own. They have donkey ears and a horse's strength, and are famous for carrying loads.", from: "Symphosius, a Latin riddle of about 400 AD (retold)" },
    { id: "p5-whetstone", d: "hard", q: "I have no edge of my own, yet every edge in the house comes to me for help.\nThe knives arrive dull and tired; they rub against me, back and forth,\nand go away with their bite back.\nThey wear me hollow, a little more each day, and I have never cut anyone.", a: "a whetstone",
      alt: ["sharpening stone","grindstone","honing stone","knife sharpener","sharpener","sharpening steel","knife steel"],
      hints: ["I am a kind of stone.","A cook or a farmer rubs a blade on me."],
      why: "A whetstone sharpens knives, axes and scythes without having an edge of its own. Blades are rubbed back and forth across it, and over the years the stone wears hollow in the middle.", from: "New, in the style of the Anglo-Saxon riddles" },
    { id: "p5-loom", d: "hard", q: "I am a harp that no one ever plays.\nA little wooden boat runs back and forth across my strings without any water,\nand behind it, row by row, a field grows that was never sown.\nWhen the field is long enough, it is cut down and someone wears it.", a: "a loom",
      alt: ["weaving loom","hand loom","handloom","weaving machine","weavers loom"],
      hints: ["The little boat is called a shuttle.","Cloth is made on me, one thread at a time."],
      why: "A loom's warp threads are stretched tight like harp strings. The shuttle, shaped like a little boat, carries thread back and forth between them, and row by row the cloth grows until it is cut off and made into clothes.", from: "New, in the style of the Exeter Book" },
    { id: "p5-saddle", d: "hard", q: "Brown I am, and much admired, and many a racer I have tired,\nthough I never ran a single step myself.\nBuckle a belt around my belly and I will hold the heaviest man in town,\nand carry him all day long without moving a leg.", a: "a saddle",
      alt: ["riding saddle","leather saddle","western saddle"],
      hints: ["A rider sits on me.","I am strapped onto the back of a horse."],
      why: "A saddle is brown leather and much admired, and every horse that wears it gets tired, though the saddle never takes a step. With its girth buckled round, it holds a rider all day.", from: "English folk riddle (retold)" },
    { id: "p5-anvil", d: "hard", q: "I am beaten every day of my life, and I never complain:\nthe harder I am struck, the more sweetly I ring.\nRed-hot things are laid on my back to be taught their shape,\nand I wear out a hundred hammers but never lose my own.", a: "an anvil",
      alt: ["blacksmiths anvil","iron anvil"],
      hints: ["I am a heavy iron block with a pointed horn at one end.","The smith hammers glowing iron on top of me."],
      why: "An anvil is struck all day and rings under the hammer. The smith lays red-hot iron on it to shape it, and a good anvil outlasts the many hammers that beat on it.", from: "New, in the style of English folk riddles" },
    { id: "p5-fan", d: "hard", q: "I am a lady's servant, made of sticks and silk.\nWhen I am not wanted, I fold my wings like a sleeping bird;\nopen me and I am a painted garden.\nAt the ball she hides her smile behind me,\nand when the room grows hot I make a breeze that blows from nowhere.", a: "a fan",
      alt: ["hand fan","folding fan","paper fan","silk fan","ladies fan","japanese fan","chinese fan"],
      hints: ["Open me with a flick of the wrist.","Wave me in front of your face to cool down."],
      why: "A folding fan is sticks with silk or paper. Closed, it folds up like wings; opened, it shows its painted picture. Ladies hid their faces behind fans, and a wave of one makes a breeze from nowhere.", from: "New, in the style of 18th-century riddles" },
    { id: "p5-seal", d: "hard", q: "I fall hot and soft, like a red tear, and a ring kisses me hard.\nThen I stand guard over secrets I cannot read,\nand the one who breaks me is the one I was waiting for.\nOnce I am broken, no one can mend me.", a: "a wax seal",
      alt: ["wax seals","seal","sealing wax","signet","letter seal","seal on a letter"],
      hints: ["I close a letter instead of an envelope.","A king presses his ring into me so everyone knows the letter is his."],
      why: "Hot sealing wax drips onto a folded letter and a signet ring presses its mark in. The seal keeps the letter shut without knowing what it says, only the person it is meant for should break it, and a broken seal cannot be put back.", from: "New, in the old style" },
    { id: "p5-pomegranate", d: "hard", q: "I wear a little crown, though I am no king, and a coat of red leather.\nInside, behind walls as thin as paper, I keep hundreds of rubies, each in its own room.\nCrack me open carelessly and I bleed all over your shirt.\nA goddess once ate six of my jewels, and that is why the world has winter.", a: "a pomegranate",
      alt: ["pomegranate seeds","pomegranate seed"],
      hints: ["I am a fruit.","Persephone ate my seeds in the Underworld."],
      why: "A pomegranate has a crown-shaped top and a tough red skin. Inside, papery walls hold hundreds of juicy seeds like rubies, and the juice stains. In the Greek myth Persephone ate six of its seeds, so she spends half the year below and the world has winter.", from: "New, from the Greek myth of Persephone" },
    { id: "p5-mask", d: "hard", q: "I have a face, but no head behind it,\nand my eyes are only windows for somebody else's eyes.\nI smile the same smile in a storm as at a wedding.\nA fox once found me in an actor's chest and said, 'What a handsome head!' Then he looked closer and said, 'What a pity it has no brain.'", a: "a mask",
      alt: ["theatre mask","theater mask","carnival mask","masquerade mask","face mask","stage mask"],
      hints: ["Actors in ancient Greece wore me on stage.","You might wear me to a fancy-dress ball to hide who you are."],
      why: "A mask is a face with nothing behind it, and its eye holes are for the wearer's eyes. Its painted expression never changes. In Aesop's fable, a fox finds an actor's mask and admires the head, then notices there is no brain inside.", from: "Aesop's fable 'The Fox and the Mask' (retold)" },
    { id: "p5-blacksmith", d: "hard", q: "What shoemaker makes shoes without any leather,\nwith all of the four elements put together?\nFire and water, earth and air:\nand every one of his customers wears two pair.", a: "a blacksmith",
      alt: ["smith","smithy","farrier","horseshoer","horseshoe","horseshoes"],
      hints: ["His customers have four legs.","He makes his shoes from iron, at a forge."],
      why: "A blacksmith or farrier makes horseshoes from iron: the earth gives the iron, fire heats it, water cools it and bellows give the air. Every customer is a horse, so it wears two pairs.", from: "Mother Goose (retold)" },
    { id: "p5-churn", d: "hard", q: "I am big at the bottom and little at the top,\nand the stick in my middle goes flippity-flop.\nWhite goes into me, and after an hour of dancing,\nlumps of yellow gold come out, and something thin and sour is left behind.", a: "a butter churn",
      alt: ["churn","churns","butter churns","dash churn","milk churn"],
      hints: ["The white that goes in is cream from the cow.","Farm families pumped my stick up and down for ages to make something for their bread."],
      why: "An old dash churn is wide at the bottom and narrow at the top, with a stick (the dasher) that goes up and down. Cream goes in, and after a long churning the butter comes out as yellow lumps, leaving thin, sour buttermilk.", from: "English and American folk riddle (retold)" },
    { id: "p5-ink", d: "hard", q: "I am born black and I die black.\nI live in a little well that holds no water,\nand I ride out to work on the tip of a feather.\nA frightened squid hides behind a cloud of me,\nand one spilled drop of me can ruin a whole page.", a: "ink",
      alt: ["black ink","squid ink","india ink","writing ink","drop of ink"],
      hints: ["You dip a quill pen into me.","An octopus can squirt me too."],
      why: "Ink is black from first to last. It is kept in an inkwell, carried to the page on a quill made from a feather, and a squid or octopus squirts a cloud of ink to escape. One blot can spoil a page.", from: "New, in the old style" },
    { id: "p5-road", d: "hard", q: "I go all the way from London to York, and I never take a step.\nI lie still in the rain and the snow while a thousand feet and wheels run over my back.\nI never get tired, though everyone who uses me does,\nand I am always at the far end before they arrive.", a: "a road",
      alt: ["the road","highway","street","lane","roadway","motorway","the way"],
      hints: ["Every traveller uses me, but I stay right where I am.","Cars drive along me and people walk beside me."],
      why: "A road stretches from one town to another without ever moving. It lies in all weather while people and carts go over it, and it is already at the far end before any traveller gets there.", from: "English folk riddle (retold)" },
    { id: "p5-scythe", d: "hard", q: "I have a single long tooth, curved like the new moon,\nand I eat a whole meadow without swallowing a blade.\nI walk the field in a man's arms, hissing as I go,\nand wherever I have been, the grass lies down in rows to dry.", a: "a scythe",
      alt: ["sickle","sickles"],
      hints: ["Farmers once used me to cut hay by hand.","Old Father Time carries me over his shoulder."],
      why: "A scythe has one long curved blade like a crescent moon. Swung through a meadow with a hiss, it cuts the grass without eating any, leaving it in rows to dry into hay.", from: "New, in the style of English folk riddles" },
    { id: "p5-moat", d: "hard", q: "I am a ring that no one wears, wrapped round a house of stone.\nI am a river that never runs anywhere.\nI guard a king with nothing but cold water,\nand I let his friends across only when he lowers a long wooden tongue over me.", a: "a moat",
      alt: ["castle moat"],
      hints: ["You would find me round a castle.","The drawbridge comes down across me."],
      why: "A moat circles a castle like a ring of still water that flows nowhere, keeping enemies out. Friends cross only when the drawbridge, the wooden tongue, is lowered over it.", from: "New, in the old style" },
    { id: "p5-windmill", d: "medium", q: "I stand on a hill and wave my four great arms at everyone who passes,\nbut I never take a step.\nI have no teeth, yet I chew up all the farmer's grain,\nand I only work when the sky breathes on me.", a: "a windmill",
      alt: ["wind mill","mill","flour mill"],
      hints: ["Don Quixote once charged at me, thinking I was a giant.","The wind turns my sails, and I grind wheat into flour."],
      why: "A windmill stands on a hill with four sails turning like waving arms. Its millstones grind grain into flour, and it only works when the wind blows.", from: "New, in the style of English folk riddles" },
    { id: "p5-scarecrow", d: "medium", q: "I stand in the field all day and all night with my arms held wide,\nbut nobody ever comes to hug me.\nI wear clothes that nobody else wanted,\nand I have only one job, to frighten. Even that I do badly, because I never move.", a: "a scarecrow",
      alt: ["scare crow"],
      hints: ["I work on a farm.","The birds are supposed to be afraid of me."],
      why: "A scarecrow stands in a field with its arms stretched out, dressed in old clothes. It is there to frighten birds off the crops, though clever birds soon learn that it never moves.", from: "New, in the style of folk riddles" },
    { id: "p5-bat", d: "medium", q: "I am a bird with no feathers and a mouse with wings.\nI hang upside down to sleep through the sunshine,\nand I go hunting in the dark,\nfinding my supper by listening to my own shouts.", a: "a bat",
      alt: ["fruit bat","vampire bat","flying fox"],
      hints: ["I come out at dusk.","I find my way by echoes."],
      why: "A bat flies but has no feathers, and looks like a mouse with leathery wings. It sleeps upside down by day and hunts at night by listening to its squeaks bounce back.", from: "Symphosius, a Latin riddle of about 400 AD (retold)" },
    { id: "p5-mousetrap", d: "medium", q: "I offer a free supper to anyone small enough to come in,\nbut my guest never gets up from the table.\nI sit very quietly in the corner with cheese on my tongue,\nand if I did my job every night, the cat would be out of work.", a: "a mousetrap",
      alt: ["mouse trap","mouse traps","trap","rat trap"],
      hints: ["Small squeaking visitors should stay well away from me.","I snap shut."],
      why: "A mousetrap is baited with cheese, a free meal for a mouse, but it snaps shut on whoever takes it. It does the same job as the house cat.", from: "New, in the style of English folk riddles" },
    { id: "p5-cradle", d: "medium", q: "I rock like a boat, but I never go to sea.\nMy sailor cannot walk or talk,\nand spends the whole voyage sleeping and crying.\nAfter a year or so my sailor grows too big for me, and I am put away in the attic.", a: "a cradle",
      alt: ["crib","bassinet","cot","moses basket","baby cradle"],
      hints: ["A baby sleeps in me.","Rock-a-bye baby, on the treetop..."],
      why: "A cradle is a baby's bed that rocks from side to side but goes nowhere. Its passenger is a baby who cannot walk or talk yet, and soon outgrows it.", from: "New, in the style of Mother Goose" },
    { id: "p5-fishhook", d: "medium", q: "I am a crooked little fellow, bent like a question,\nand I go swimming with a worm on my back.\nI offer the fish a free dinner,\nand then the fish becomes the dinner.", a: "a fishhook",
      alt: [],
      hints: ["You need me to go fishing.","I hang on the end of a fishing line."],
      why: "A fishhook is bent like a question mark and goes into the water with a worm on it. The fish thinks it has found a free meal, and ends up as somebody else's.", from: "New, in the style of English folk riddles" },
    { id: "p5-oar", d: "medium", q: "I have a long neck and one flat foot,\nand I only ever walk in the water.\nI bow to the river, push it behind me and lift my dripping foot again,\nand the one who works me sits facing backward to go forward.", a: "an oar",
      alt: ["paddle","rowing oar"],
      hints: ["You need two of me to row a boat.","I am a long wooden pole with a flat blade at the end."],
      why: "An oar has a long shaft and a flat blade. It dips into the water, pushes it back and comes up dripping, and a rower sits facing the back of the boat to move it forward.", from: "New, in the style of the Exeter Book" },
    { id: "p5-thistle", d: "medium", q: "I am a soldier in prickly green armour, with a purple helmet on my head.\nI guard a whole country, and once, so the story goes, I saved it,\nwhen a barefoot raider stepped on me in the dark and cried out.\nWhen I am old, my hair turns white and flies away on the wind.", a: "a thistle",
      alt: ["scottish thistle","scotch thistle","thistledown","thistle down"],
      hints: ["I am a prickly plant.","I am the emblem of Scotland."],
      why: "A thistle has spiky leaves and a purple flower head like a helmet. It is the emblem of Scotland: legend says a Viking raider trod on one barefoot and his yell woke the Scots. Its seeds float off on white down.", from: "Scottish legend (new riddle)" },
    { id: "p5-spinningwheel", d: "medium", q: "My one foot is pushed by somebody else's foot, and my round body hums as it turns.\nA cloud of fluff goes into my hands,\nand a thread as long as a road comes out.\nA princess once pricked her finger on me and slept for a hundred years.", a: "a spinning wheel",
      alt: ["spinning wheels","spinningwheel","spindle","spindles"],
      hints: ["Wool is turned into yarn on me.","I have a big wheel worked by a foot pedal."],
      why: "A spinning wheel is driven by a foot treadle and hums as its wheel turns, twisting fluffy wool into long thread. In Sleeping Beauty the princess pricks her finger on a spindle and sleeps for a hundred years.", from: "New, from the tale of Sleeping Beauty" },
    { id: "p5-signpost", d: "medium", q: "I have arms but no hands,\nand they point to places I have never been.\nI stand where the roads meet, in every kind of weather,\nand I show every stranger the way, though I cannot walk a single step of it.", a: "a signpost",
      alt: ["sign post","fingerpost","finger post","road sign","sign","guidepost","street sign","waymarker"],
      hints: ["You find me at a crossroads.","My arms have the names of towns written on them."],
      why: "A signpost's arms point to towns it has never visited. It stands at a crossroads in all weather and shows travellers the way without ever moving.", from: "New, in the style of English folk riddles" },
    { id: "p5-nutcracker", d: "medium", q: "I am a little wooden soldier with a great big jaw.\nI will bite anything with a hard shell,\nbut I never swallow a crumb: I hand you the best part and keep nothing for myself.\nAt Christmas I come down from the shelf, and in the ballet I come to life.", a: "a nutcracker",
      alt: ["nut cracker","nut crackers","nutcracker soldier"],
      hints: ["People put me out at Christmas.","I break open walnuts and hazelnuts."],
      why: "A nutcracker is often carved like a toy soldier with a big lever jaw. It cracks hard shells but gives the nut to you, and in Tchaikovsky's ballet it comes to life on Christmas Eve.", from: "German folk tradition (new riddle)" },
    { id: "p5-axe", d: "medium", q: "I have one tooth and a long wooden neck.\nI walk into the woods, and the woods fall down before me.\nThe trees themselves gave me my neck,\nand I repay them by biting them at the ankle until they topple.", a: "an axe",
      alt: ["axes","ax","hatchet","hatchets","wood axe","woodcutters axe","felling axe"],
      hints: ["A woodcutter carries me over his shoulder.","Swing me and the chips fly."],
      why: "An axe has one sharp blade and a long wooden handle, and it cuts at the base of a tree until it falls. In Aesop's fable the trees gave the woodcutter a branch for a handle, and he used it to cut them all down.", from: "Aesop's fable 'The Woodcutter and the Trees' (retold)" },
    { id: "p5-barrel", d: "medium", q: "My belly is round, my ribs are wooden, and iron belts keep me from bursting.\nI stand on my end or roll on my side,\nand people knock on my head to find out what is inside me.\nWhen I am full I am too heavy to lift; when I am empty, I am the loudest thing in the cellar.", a: "a barrel",
      alt: ["cask","keg","wooden barrel","water barrel","hogshead"],
      hints: ["A cooper makes me.","Pirates keep their water and apples in me."],
      why: "A barrel is bellied and made of wooden staves held tight by iron hoops. It can stand or roll, and knocking on it tells you how full it is. As the saying goes, empty barrels make the most noise.", from: "New, in the style of English folk riddles" },
    { id: "p5-flag", d: "medium", q: "I have no voice, yet I speak for a whole country.\nI cannot walk, but I dance all day without ever leaving my pole,\nthough only when the wind asks me to.\nSoldiers follow me into battle, and when someone great dies, I am lowered halfway.", a: "a flag",
      alt: ["banner","national flag","standard","ensign"],
      hints: ["I am a piece of cloth with colours and a pattern.","I fly at the top of a pole."],
      why: "A flag stands for a country without saying a word. It flutters on its pole only when the wind blows, armies carried flags into battle, and flags fly at half-mast when someone important dies.", from: "New, in the old style" },
    { id: "p5-countryside", d: "hard", q: "Put \"the\" in front of my name and shuffle every letter, and you get a promise: NO CITY DUST HERE. Where am I?", a: "the countryside",
      alt: ["countryside","country side"],
      hints: ["It's an anagram of THE + my name: fourteen letters in all.","Fields, hedges, cows and fresh air: the opposite of town."],
      why: "THE COUNTRYSIDE and NO CITY DUST HERE use exactly the same fourteen letters.", from: "folk riddle, reworded" },
    { id: "p5-mine", d: "hard", q: "Ask \"Whose is this?\" and if it belongs to you, you'll answer with me. Dwarves march into me every morning, singing, and come out with gold.", a: "mine",
      alt: ["a mine"],
      hints: ["One small word that is both a word for \"belonging to me\" and a place.","\"That's not yours, it's ___!\" Miners work in one."],
      why: "\"Mine\" means belonging to me, and a mine is the tunnel people dig to get gold, coal or gems out of the ground.", from: "new" },
    { id: "p5-club", d: "hard", q: "Golfers swing me. Cavemen carried me. On a playing card I'm a little black three-leafed clover. And you can join me, but only if they let you in.", a: "a club",
      alt: ["club"],
      hints: ["One short word with four meanings. One of the four card suits.","Hearts, diamonds, spades and ___s."],
      why: "A club is a golf stick, a caveman's heavy stick, a card suit, and a group you can join.", from: "new" },
    { id: "p5-dormitory", d: "hard", q: "Shuffle my nine letters and they spell DIRTY ROOM, which, to be honest, is often exactly what I am. What am I?", a: "a dormitory",
      alt: ["dormitory","dormitories","dorm","dorms","dorm room"],
      hints: ["It's an anagram: use every letter of DIRTY ROOM once.","Lots of children sleep in me on a school trip or at a boarding school."],
      why: "DORMITORY and DIRTY ROOM use exactly the same nine letters.", from: "folk riddle, reworded" },
    { id: "p5-astronomer", d: "hard", q: "Rearrange my letters and you get MOON STARER, which is a fair description of my job. Who am I?", a: "an astronomer",
      alt: ["astronomer","astronomers"],
      hints: ["It's an anagram: use every letter of MOON STARER once.","I work at night with a telescope, but I'm not an astronaut."],
      why: "ASTRONOMER and MOON STARER use exactly the same ten letters.", from: "folk riddle, reworded" },
    { id: "p5-pattern", d: "hard", q: "My first is a tap, soft and friendly and light.\nMy second's a seabird in black cap and white.\nMy whole you will find on a jumper or tile:\nthe same little shape, again, all the while.", a: "a pattern",
      alt: ["pattern","patterns"],
      hints: ["A charade: two small words joined. A gentle tap on the head is a ___.","The seabird is a tern."],
      why: "PAT (a light tap) + TERN (a black-capped seabird) = PATTERN, a shape repeated over and over.", from: "new" },
    { id: "p5-legend", d: "hard", q: "My first has a knee and stands on a foot.\nMy second comes last in every story.\nMy whole is a tale too old to check,\nand the little box on a map that explains its signs.", a: "a legend",
      alt: ["legend","legends"],
      hints: ["A charade: two small words joined. You have two of my first.","My first is a LEG. My second is the last word of a fairy tale: \"The ___.\""],
      why: "LEG + END = LEGEND: an old story nobody can prove, and also the key on a map.", from: "new" },
    { id: "p5-catalogue", d: "hard", q: "My first purrs on your lap. My second is the smallest word there is. My third was cut from a tree and burns on the fire. Put the three together and I'm a long list, usually with pictures.", a: "a catalogue",
      alt: ["catalogue","catalog","catalogues","catalogs"],
      hints: ["A charade of three small words. The first is a pet.","CAT + A + a piece of firewood."],
      why: "CAT + A + LOG = CATALOG (or catalogue): a long list of things, often with pictures.", from: "new" },
    { id: "p5-earnest", d: "hard", q: "My first hears every word you say.\nMy second holds eggs high up in a tree.\nMy whole is serious, and means every word.", a: "earnest",
      alt: ["in earnest","earnestly"],
      hints: ["A charade: a body part, then a bird's home.","EAR + ____."],
      why: "EAR + NEST = EARNEST, which means serious and sincere.", from: "new" },
    { id: "p5-princess", d: "hard", q: "Here comes a whole crowd of a king's sons. Add one letter to the end of them, and suddenly there's only one of her. Who is she?", a: "a princess",
      alt: ["princess","princesses"],
      hints: ["Write down the word for several of a king's sons.","PRINCES + one more S."],
      why: "PRINCES (lots of royal sons) + S = PRINCESS (one royal daughter). An S usually makes more, but here it makes one.", from: "new" },
    { id: "p5-polish", d: "hard", q: "Give me a capital letter and I come from Warsaw. Take it away and I make your old shoes shine. Strangely, you don't say me the same way twice.", a: "polish",
      alt: ["shoe polish","polishing"],
      hints: ["Warsaw is the capital of Poland.","People from Poland are ___. You rub shoe ___ on with a cloth."],
      why: "Polish (POH-lish) means from Poland; polish (POL-ish) is what you rub on to make things shine. One capital letter changes the word.", from: "new" },
    { id: "p5-nice", d: "hard", q: "With a capital letter, I'm a sunny city on the French coast, and I rhyme with \"peace\". Without one, I rhyme with \"mice\", and I'm what you hope people will call you.", a: "nice",
      alt: [],
      hints: ["It's the same four letters both times. Only the capital and the sound change.","Santa's list has two sides: naughty and ___."],
      why: "Nice (said \"neess\") is a city on the French Riviera; nice (rhymes with mice) means kind and pleasant.", from: "new" },
    { id: "p5-refuse", d: "hard", q: "Stress my first half and I'm the rubbish a garbage truck takes away. Stress my second half and I'm what you do when you just won't.", a: "refuse",
      alt: [],
      hints: ["One spelling, two ways to say it: REF-use and re-FUSE.","To say no to something is to ___ it."],
      why: "REF-use is rubbish; re-FUSE means to say no. Same letters, different stress, different word.", from: "new" },
    { id: "p5-content", d: "hard", q: "Stress my first half and I'm what's inside the box. Stress my second half and I'm how you feel when you don't need a single thing more.", a: "content",
      alt: ["contents"],
      hints: ["One spelling, two ways to say it: CON-tent and con-TENT.","The list at the front of a book is the table of ___s."],
      why: "CON-tent is what something holds; con-TENT means happy and satisfied.", from: "new" },
    { id: "p5-fine", d: "hard", q: "A parking ticket can be me. So can a sunny day, a thread thinner than a hair, and the answer most people give to \"How are you?\", even when I'm not true.", a: "fine",
      alt: [],
      hints: ["One small word with lots of meanings. You might have to pay me.","\"I'm ___, thanks.\" \"The weather's ___ today.\""],
      why: "A fine is money you pay as a punishment, fine weather is sunny, a fine thread is very thin, and \"I'm fine\" is the usual answer to \"How are you?\"", from: "new" },
    { id: "p5-pitch", d: "hard", q: "Footballers run on me. Singers try to hit me. A baseball player throws me. Old sailors sealed their ships with me, black and sticky. And campers do me to a tent.", a: "pitch",
      alt: ["pitches"],
      hints: ["It's one word with five meanings.","A football field in Britain is a ___, and how high a note sounds is its ___."],
      why: "A pitch is a sports field, how high a note is, a throw in baseball, the black tar that sealed wooden ships, and what you do when you put up a tent.", from: "new" },
    { id: "p5-oversight", d: "hard", q: "When I'm someone's job, they're watching everything closely. When I'm someone's mistake, nobody was watching at all. What am I?", a: "an oversight",
      alt: ["oversight","oversights"],
      hints: ["One word that means two opposite things. It starts with OVER.","The people who check on a project have ___ of it. Forgetting to check is also an ___."],
      why: "Oversight means watching over something carefully, and also a mistake made because nobody noticed. One word, two opposite meanings.", from: "new" },
    { id: "p5-left", d: "hard", q: "When everyone has done me, the room is empty. Yet whatever is me is still in the room. And I'm always on one side of you.", a: "left",
      alt: [],
      hints: ["Think of one word that means both \"gone\" and \"still here\".","\"They all ___ the party, and there was cake ___ over.\" And it's the opposite of right."],
      why: "When everyone has left, the room is empty, but whatever is left stays behind. Left means both gone and remaining, and it's a side too.", from: "new" },
    { id: "p5-adrift", d: "hard", q: "When is a boat just like the heap of snow that piles up against your door?", a: "when it's adrift",
      alt: ["adrift","a drift","when it is a drift","+adrift","+drift"],
      hints: ["What do you call a pile of snow the wind has blown against a wall?","A snow ___. A boat floating loose with nothing to steer it is a___."],
      why: "A heap of blown snow is a drift, and a boat floating loose is adrift: \"a drift\".", from: "folk riddle, reworded" },
    { id: "p5-elder", d: "hard", q: "Which tree should all the other trees treat with respect, since its very name says it was born first?", a: "an elder",
      alt: ["elder","elders","elder tree","elderberry","elderberry tree","elderflower"],
      hints: ["It's a pun. Think of another word for \"older\".","Grown-ups say \"respect your ___s\". There's a tree by that name, with white flowers and dark berries."],
      why: "The elder is a real tree (elderberries, elderflowers), and \"elder\" also means older.", from: "new" },
    { id: "p5-knot", d: "hard", q: "Pull me tight and I'll hold fast. Take away my first letter and I sound exactly the same, but now all I ever do is say no.", a: "a knot",
      alt: ["knot","knots"],
      hints: ["My first letter is silent.","Take the K off me and you get a little word that means \"no\"."],
      why: "KNOT and NOT sound the same, because the K is silent. A knot holds fast; \"not\" says no.", from: "new" },
    { id: "p5-funnybone", d: "hard", q: "Swap the first sounds of my two words and I become a rabbit's telephone. Bang me on a door frame and, whatever my name says, you won't be laughing.", a: "your funny bone",
      alt: ["funny bone","funnybone","funny bones","+funny bone"],
      hints: ["A rabbit is a bunny, a telephone is a phone. Now swap their first sounds.","BUNNY PHONE becomes ___ ___. It's in your elbow."],
      why: "Swap the B and the F sounds in BUNNY PHONE and you get FUNNY BONE, the spot on your elbow that tingles, not tickles, when you knock it.", from: "new" },
    { id: "p5-bound", d: "hard", q: "A train heading for London is me. A prisoner tied up with rope is me. A deer clearing a fence in one leap does me. And if you're certain to win, you're me to.", a: "bound",
      alt: ["bounds"],
      hints: ["One small word with four meanings. It rhymes with \"found\".","\"Homeward ___\", \"___ hand and foot\", \"leaps and ___s\"."],
      why: "Bound means heading somewhere, tied up, a big leap, and certain (\"bound to win\").", from: "new" },
    { id: "p5-often", d: "medium", q: "I'm a five-letter word. Take away my first two letters and ten are left. And I'm the opposite of \"hardly ever\".", a: "often",
      alt: [],
      hints: ["Don't count anything. \"Ten\" is a word hiding inside me.","__TEN. Not rarely, but..."],
      why: "Take OF off OFTEN and you're left with TEN.", from: "folk riddle, reworded" },
    { id: "p5-few", d: "medium", q: "I'm a little word of three letters. Add two more to my end and there are less of me than before.", a: "few",
      alt: [],
      hints: ["Look for a word that means \"not many\".","Add -ER to me."],
      why: "Add ER to FEW and you get FEWER. Adding letters made it fewer.", from: "folk riddle, reworded" },
    { id: "p5-scold", d: "medium", q: "Whole, I'm what a cross grown-up does when you've been naughty. Cut off my head and I'm chilly. Cut off my head again and I'm ancient.", a: "scold",
      alt: ["scolding","scolds","to scold"],
      hints: ["Each time you cut off my head, take away my first letter.","Chilly: COLD. Ancient: OLD. Now put one letter in front."],
      why: "SCOLD without its S is COLD; without the C as well, it's OLD.", from: "new" },
    { id: "p5-carnation", d: "medium", q: "My first has four wheels and a horn.\nMy second has a flag, an anthem and borders.\nMy whole is a flower you might pin to a jacket at a wedding.", a: "a carnation",
      alt: ["carnation","carnations"],
      hints: ["A charade: two words joined. The first is a vehicle.","CAR + another word for a country."],
      why: "CAR + NATION = CARNATION, a frilly flower often worn in a buttonhole.", from: "new" },
    { id: "p5-brother", d: "medium", q: "Start with a thin soup. Add the noise people make when they can't think what to say next. Now you have someone who shares your parents, and maybe your bedroom.", a: "a brother",
      alt: ["brother","brothers","bro","big brother","little brother"],
      hints: ["The thin soup is a five-letter word, often chicken.","BROTH + ER."],
      why: "BROTH + ER = BROTHER.", from: "new" },
    { id: "p5-candy", d: "medium", q: "You're only allowed two letters. How do you spell CANDY?", a: "C and Y",
      alt: ["cy","c y","c and a y"],
      hints: ["Read CANDY slowly and look for a little word hiding in the middle.","Say the first letter, then the middle word, then the last letter."],
      why: "CANDY is just C AND Y.", from: "folk riddle, reworded" },
    { id: "p5-reward", d: "medium", q: "Do something brave or kind and you might get me. Spell me backwards and I'm where your socks are hiding.", a: "a reward",
      alt: ["reward","rewards"],
      hints: ["Which piece of furniture keeps your socks? Spell it backwards.","DRAWER backwards."],
      why: "REWARD is DRAWER spelled backwards.", from: "new" },
    { id: "p5-change", d: "medium", q: "Why will an empty purse be exactly the same tomorrow as it is today?", a: "there's no change in it",
      alt: ["no change","+no change","there is no change"],
      hints: ["What do you call the coins you get back at a shop?","Nothing about it will ___, because there's no ___ in it."],
      why: "\"Change\" means coins, and it also means becoming different. An empty purse has no change in it, so it never changes.", from: "folk riddle, reworded" },
    { id: "p5-dove", d: "medium", q: "Rhyme me with \"glove\" and I coo on the rooftop. Rhyme me with \"drove\" and I've already hit the water headfirst.", a: "a dove",
      alt: ["dove","doves"],
      hints: ["One spelling, two sounds: a bird, and something you did yesterday.","Today I dive into the pool. Yesterday I ___."],
      why: "A dove (rhymes with glove) is a bird; dove (rhymes with drove) is what you did when you dived.", from: "new" },
    { id: "p5-longunderwear", d: "medium", q: "Read this like a picture:\nWEAR\nLONG\nWhat would you put on for a freezing winter's day?", a: "long underwear",
      alt: ["long under wear","+long underwear"],
      hints: ["Where is LONG? It is ___ WEAR.","LONG is under WEAR."],
      why: "LONG is written under WEAR: long underwear.", from: "new" },
    { id: "p5-radar", d: "medium", q: "I go out and come back exactly the way I went. Write me down and I do just the same. Pilots trust me when they can't see a thing.", a: "radar",
      alt: ["radars"],
      hints: ["Read me backwards: nothing changes.","I bounce radio waves off planes and ships. Five letters, the same both ways."],
      why: "Radar sends out a signal that bounces straight back, and the word RADAR reads the same backwards.", from: "new" },
    { id: "p5-aha", d: "medium", q: "I'm three letters long. Read me backwards and nothing changes. Hold me up to a mirror and nothing changes. The ancient Greeks shouted \"Eureka!\"; you'll say me when the penny drops.", a: "aha",
      alt: ["ah ha"],
      hints: ["I'm something you say, not something you hold.","I start and end with the first letter of the alphabet."],
      why: "AHA reads the same both ways, its capital letters look the same in a mirror, and it's what you say when you finally get it.", from: "new" },
    { id: "p5-harp", d: "medium", q: "My first is in hat but never in cat.\nMy second's in lamb but never in limb.\nMy third is in rope but never in hope.\nMy fourth is in pear but never in bear.\nMy whole has strings, but I'm no puppet or kite:\nI'm plucked, and angels play me on clouds of white.", a: "a harp",
      alt: ["harp"],
      hints: ["Find the one letter in each first word that isn't in the second.","The letters are H, A, R and P."],
      why: "Hat not cat gives H, lamb not limb gives A, rope not hope gives R, pear not bear gives P: HARP.", from: "new" },
    { id: "p5-fast", d: "medium", q: "A sprinter is me. A door jammed so tight it won't budge is stuck me. And if you skip every meal for a whole day, you're doing me.", a: "fast",
      alt: ["fasting"],
      hints: ["One word: quick, firmly fixed, and going without food.","\"Stuck ___\", \"as ___ as lightning\", and the morning meal is break___."],
      why: "Fast means quick, firmly stuck (\"stuck fast\"), and going without food. Breakfast is when you break your fast.", from: "new" },
    { id: "p5-deafparrot", d: "hard", q: "A pet-shop owner promised that her parrot would repeat every word it heard. The buyer took it home and chatted to it for weeks, but it never said a thing. The owner hadn't told a lie. How?", a: "the parrot is deaf",
      alt: ["deaf parrot","deaf","it was deaf","+deaf","+can not hear","+could not hear","+no hearing","+hard of hearing"],
      hints: ["Read her promise again: every word it heard.","How many words did the parrot actually hear?"],
      why: "The parrot was deaf. It really would repeat every word it heard, but it never heard a single one.", from: "classic puzzle, reworded" },
    { id: "p5-wallbuilt", d: "hard", q: "It took six builders eight days to build a garden wall. How long would it take three builders to build it?", a: "it's already built",
      alt: ["+already built","+built already","+already been built","+already finished","+already done","+already there","+already up","+no day","+no already"],
      hints: ["Read the last two words of the question again.","Which wall are the three builders being asked about?"],
      why: "The wall in the question is the one the six builders already finished. Nobody needs to build it again.", from: "classic puzzle, reworded" },
    { id: "p5-swapcamels", d: "hard", q: "An old king tells his two sons to race their camels to a distant oasis. The son whose camel arrives LAST will inherit the kingdom. For days the brothers hardly move. Then a wise woman whispers two words to them, and they leap up and race off as fast as they can. What did she say?", a: "swap camels",
      alt: ["swap","switch camels","trade camels","exchange camels","+swap","+swop","+switch","+exchange","+trade","+other camel","+each other camel","+ride brother"],
      hints: ["Each brother wants the other one's camel to get there first.","What if neither of them was riding his own camel?"],
      why: "If each brother rides the other's camel, then getting there first makes his own camel arrive last. So both race flat out.", from: "classic puzzle, reworded" },
    { id: "p5-pushcork", d: "hard", q: "A coin is trapped inside an empty glass bottle with a cork in its neck. How can you get the coin out without pulling out the cork or breaking the bottle?", a: "push the cork into the bottle",
      alt: ["push the cork in","+push cork","+cork in","+cork into","+press cork","+cork down","+poke cork","+shove cork","+force cork","+cork inside","+cork fall"],
      hints: ["You can't pull the cork out. But there's another way it can go.","What if the cork ended up inside too?"],
      why: "Push the cork down into the bottle, then tip the coin out of the open neck. The cork never came out and the bottle is in one piece.", from: "classic puzzle, reworded" },
    { id: "p5-lastapple", d: "hard", q: "A basket holds five apples. Five girls each take one apple, yet one apple is still in the basket. How?", a: "the last girl took the basket too",
      alt: ["+took basket","+basket too","+whole basket","+with basket","+basket and all","+in basket","+still in basket","+kept in basket","+left in basket","+carried basket"],
      hints: ["The last girl took her apple in a special way.","Where was the fifth apple when she walked off with it?"],
      why: "The fifth girl took the basket with her apple still inside it. Every girl has an apple, and one is still in the basket.", from: "classic puzzle, reworded" },
    { id: "p5-warmbulb", d: "hard", q: "Three switches outside a closed room work one light bulb inside it. You can flip the switches as often as you like, but you may open the door and go in only once. How can you tell which switch works the bulb?", a: "feel if the bulb is warm",
      alt: ["+bulb warm","+bulb hot","+warm bulb","+feel bulb","+touch bulb","+bulb heat","+heat up","+heats up","+feel heat","+feel warm","+feel hot","+warm up","+bulb temperature","+still warm","+leave one on"],
      hints: ["A bulb gives off more than light.","Leave one switch on for a few minutes, then turn it off again."],
      why: "Turn switch one on for a few minutes, then off, and turn switch two on. Go in: lit means switch two, dark but warm means switch one, cold means switch three.", from: "classic puzzle, reworded" },
    { id: "p5-scruffybarber", d: "hard", q: "A small town has only two barbers, and they cut each other's hair. One always looks perfectly neat; the other's hair is a scruffy mess. Which barber should you go to?", a: "the scruffy one",
      alt: ["scruffy barber","the messy one","+scruffy","+messy","+untidy","+scruffier","+bad haircut","+worse haircut","+terrible haircut","+awful haircut","+shaggy","+unkempt"],
      hints: ["Who gave the neat barber his haircut?","Each barber's head shows off the other one's work."],
      why: "The scruffy barber gave the neat one his smart haircut, and the neat barber made the mess. Go to the one who does the good work.", from: "classic puzzle, reworded" },
    { id: "p5-pennies", d: "hard", q: "Why are 1990 pennies worth more than 1980 pennies?", a: "there are ten more of them",
      alt: ["ten more","+ten more","+more penny","+more coin","+more of them","+ten extra","+bigger number","+ten cent more"],
      hints: ["It has nothing to do with how old the coins are.","Count them."],
      why: "1,990 pennies is ten more pennies than 1,980, so they are worth ten cents more. The year stamped on them never comes into it.", from: "classic puzzle, reworded" },
    { id: "p5-newyearsday", d: "hard", q: "Two days ago, Ruby was nine. Next year, she will turn twelve. How can that be?", a: "her birthday is 31 December",
      alt: ["+31 december","+december 31st","+31st december","+dec 31","+31 dec","+december thirty first","+new year eve","+january 1","+january 1st","+1st january","+january first","+first january","+jan 1","+new year day","+last day of year","+end of december","+last day december"],
      hints: ["Today is a very special day of the year.","Her birthday was yesterday."],
      why: "Today is 1 January. Ruby was 9 two days ago, turned 10 yesterday on 31 December, turns 11 at the end of this year and 12 at the end of next year.", from: "classic puzzle, reworded" },
    { id: "p5-parkedplane", d: "hard", q: "A woman jumped out of an aeroplane with no parachute and landed safely on her own two feet. How?", a: "the plane was on the ground",
      alt: ["+on ground","+on runway","+plane parked","+parked","+landed","+not flying","+not in air","+not airborne","+not taken off","+not take off","+on tarmac","+grounded","+not moving","+stationary plane"],
      hints: ["Nobody said the plane was in the sky.","Where do planes spend most of their time?"],
      why: "The plane was parked on the ground, so she just hopped down. A parachute only matters when the plane is flying.", from: "classic puzzle, reworded" },
    { id: "p5-vicar", d: "hard", q: "A woman in a small town has married more than three hundred men. She has never been divorced, none of the men has died, and she has never broken the law. How?", a: "she's a vicar",
      alt: ["vicar","priest","registrar","celebrant","minister","+vicar","+priest","+registrar","+celebrant","+officiant","+minister","+pastor","+reverend","+rabbi","+judge","+chaplain","+clergy","+performs weddings","+does weddings","+runs weddings","+conducts weddings","+marries couple","+marries people","+officiate"],
      hints: ["She was at every one of those weddings, but never as the bride.","Who says \"I now pronounce you husband and wife\"?"],
      why: "She's a vicar. She has married hundreds of men to their brides at their weddings, without ever marrying any of them herself.", from: "classic puzzle, reworded" },
    { id: "p5-chessfriends", d: "hard", q: "Two friends played chess all afternoon. Each of them played five games and won all five, and there were no draws. How?", a: "they weren't playing each other",
      alt: ["+not each other","+not against each other","+not with each other","+different opponents","+other people","+other players","+other opponents","+someone else","+different people","+played others","+against computer","+played computer","+other friends","+separate games","+not together"],
      hints: ["Ten games, ten wins between them.","Who said they were playing against each other?"],
      why: "Each of them played five games against somebody else. Ten games, ten wins, and none of them was against each other.", from: "classic puzzle, reworded" },
    { id: "p5-taxi", d: "hard", q: "A passenger chatted so much that her taxi driver pointed at his ears and mouth and shook his head, as if he couldn't hear or speak. She sat quietly for the rest of the trip. Only when she got out did she realise he had been pretending. How?", a: "he took her where she'd asked",
      alt: ["+where","+address","+destination","+right place","+heard her","+took her","+drove her","+directions","+asked for","+told him"],
      hints: ["Think back to the moment she got in.","How did he know where to go?"],
      why: "She told him where she wanted to go when she got in, and he took her straight there. So he must have heard her.", from: "classic puzzle, reworded" },
    { id: "p5-looserope", d: "hard", q: "A dog is tied to a three-metre rope, yet it trots over to a bone ten metres away and starts chewing it. How?", a: "the rope isn't tied to anything",
      alt: ["+not tied","+untied","+other end","+rope loose","+loose rope","+not attached","+unattached","+free end","+loose end","+dragging rope","+drags rope","+tied to nothing","+rope free"],
      hints: ["The dog is tied to the rope. Now look at the rope.","What is at the far end of the rope?"],
      why: "The dog is tied to the rope, but the rope's other end isn't tied to anything. The dog just drags it along.", from: "classic puzzle, reworded" },
    { id: "p5-underdoor", d: "hard", q: "A brother and sister stand on the same sheet of newspaper, one at each end, but however hard they try, they can't touch each other. How?", a: "it's slid under a closed door",
      alt: ["under a door","+under door","+door between","+doorway","+closed door","+door closed","+door shut","+shut door","+through door","+other side door","+either side door"],
      hints: ["Something stands between them.","The newspaper goes underneath something in the house."],
      why: "The newspaper is pushed under a door, and they stand on it on either side with the door shut between them.", from: "classic puzzle, reworded" },
    { id: "p5-sugar", d: "hard", q: "Mum found a fly in her coffee and sent it back. The waiter brought her a fresh cup, but after one sip she said, \"This is the same coffee!\" How did she know?", a: "she'd already put sugar in it",
      alt: ["+put sugar","+added sugar","+sugar in","+already sugar","+sugared","+sweetened","+tasted sweet","+was sweet","+already sweet","+sugary","+had sugar"],
      hints: ["She did something to the first cup before she spotted the fly.","Taste it."],
      why: "She had sugared the first cup before spotting the fly. The \"fresh\" cup was already sweet, so it was the same coffee with the fly fished out.", from: "classic puzzle, reworded" },
    { id: "p5-shipladder", d: "hard", q: "A rope ladder hangs over the side of a ship in harbour, its bottom rung just touching the water. Over six hours the tide rises two metres. How far up the ladder does the water reach now?", a: "the same rung as before",
      alt: ["+same rung","+same place","+same level","+same as before","+same spot","+same height","+where it was","+still touching","+still bottom","+just bottom","+only bottom","+ship rise","+ship float","+boat rise","+boat float","+rise with","+floats up","+no higher","+unchanged"],
      hints: ["What happens to a ship when the tide comes in?","The ladder is fixed to the ship, not to the harbour wall."],
      why: "The ship floats, so it rises with the tide, and the ladder rises with it. The water still just touches the bottom rung.", from: "classic puzzle, reworded" },
    { id: "p5-lorry", d: "hard", q: "A truck gets stuck under a low bridge: it is half an inch too tall to fit. While the grown-ups argue about cutting the bridge, a child suggests an easy fix. What is it?", a: "let some air out of the tires",
      alt: ["+air out","+let air","+tyre air","+tire air","+tyre pressure","+tire pressure","+deflate","+flat tyre","+flat tire","+let down tyre","+let down tire","+tyre down","+tire down","+lower tyre","+lower tire","let air out of the tyres"],
      hints: ["Don't change the bridge. Change the truck.","What is the truck sitting on?"],
      why: "Let a little air out of the tires. The truck sinks an inch or so and rolls straight under.", from: "classic puzzle, reworded" },
    { id: "p5-leaves", d: "hard", q: "From her bedroom window, Amy can see the church tower all winter long, but never in summer. The tower has not moved, and the window is perfectly clean. Why?", a: "a tree's leaves hide it",
      alt: ["+tree leaves","+tree leaf","+leaves block","+leaf block","+leaves in way","+leafy","+leaves grow","+leaves hide","+leaf hide","+leaves cover","+branches","+foliage","+tree in way","+tree block","+tree hides","+tree covers","+leaves on"],
      hints: ["Something between Amy and the tower changes with the seasons.","In autumn it goes bare."],
      why: "A tree stands between Amy's window and the church. In summer its leaves hide the tower; in winter its branches are bare and she can see straight through.", from: "new" },
    { id: "p5-concrete", d: "hard", q: "How can you drop a raw egg onto a concrete floor without cracking it?", a: "the concrete won't crack",
      alt: ["+concrete not crack","+floor not crack","+concrete crack","+floor crack","+concrete hard","+floor hard","+floor strong","+concrete strong","+floor tough","+concrete tough","+egg crack floor not"],
      hints: ["Read the question again. What does \"it\" mean?","Which is harder to crack: the egg or the floor?"],
      why: "\"It\" is the concrete floor. The egg will smash, but the floor will be fine: concrete is very hard to crack.", from: "classic puzzle, reworded" },
    { id: "p5-buseyes", d: "hard", q: "You are driving a bus. At the first stop, six people get on. At the second, two get off and four get on. At the third, everyone gets off except one man, who has fallen asleep. What colour are the bus driver's eyes?", a: "the same as yours",
      alt: ["same as mine","my eye colour","my eye color","+same as mine","+same as your","+same mine","+my eye","+your eye colour","+your eye color","+you driver","+me driver","+i drive"],
      hints: ["Read the very first sentence again.","Who is driving the bus?"],
      why: "You're the bus driver, so the driver's eyes are whatever colour yours are. All the getting on and off is there to distract you.", from: "classic puzzle, reworded" },
    { id: "p5-dryumbrella", d: "medium", q: "A family of five huddled under one small umbrella, and not one of them got wet. How?", a: "it wasn't raining",
      alt: ["no rain","+not raining","+no rain","+not rain","+sunny","+dry day","+sunshade","+sun shade","+shade"],
      hints: ["Nobody said anything about rain.","An umbrella has more than one use."],
      why: "It wasn't raining at all. They were just sharing the umbrella's shade, so of course nobody got wet.", from: "classic puzzle, reworded" },
    { id: "p5-cardoor", d: "medium", q: "Driving home late, you pull up in front of a gold door, a silver door and a wooden door. Which door do you open first?", a: "the car door",
      alt: ["car door","my car door","+car door","+vehicle door"],
      hints: ["Where are you sitting?","You have to get out first."],
      why: "You're sitting in a car, so the first door you open is the car door. Only then can you reach any of the others.", from: "classic puzzle, reworded" },
    { id: "p5-everest", d: "medium", q: "Before Mount Everest was discovered, what was the highest mountain in the world?", a: "Mount Everest",
      alt: ["everest","mt everest","+everest"],
      hints: ["Finding a mountain does not make it any taller.","It was there all along."],
      why: "Everest was the highest mountain all along. It didn't grow when someone found it; nobody had measured it yet.", from: "classic puzzle, reworded" },
    { id: "p5-butcher", d: "medium", q: "Ron works behind the counter at the butcher's. He is six feet tall, wears size eleven shoes and has a big ginger beard. What does he weigh?", a: "meat",
      alt: ["+weighs meat","+weigh meat","+meat on scale","+beef","+mince","+chops"],
      hints: ["Forget his height and his shoes.","Think about his job, and what \"weigh\" can mean."],
      why: "He weighs meat, on the scales at the butcher's counter. The height, shoes and beard are there to lead you astray.", from: "classic puzzle, reworded" },
    { id: "p5-exercisebike", d: "medium", q: "Gran cycled twenty miles before breakfast this morning, but her bike never moved an inch. How?", a: "an exercise bike",
      alt: ["exercise bicycle","static bike","stationary bike","spin bike","+exercise","+stationary","+static","+spin bike","+gym bike","+indoor bike","+turbo trainer","+bike trainer","+fitness bike","+exercycle","+peloton"],
      hints: ["She worked up a sweat, but she didn't go anywhere.","Her bike lives in the spare room."],
      why: "Gran rode an exercise bike. Its pedals and wheel spin, but it's fixed in place, so she can ride twenty miles without going anywhere.", from: "new" },
    { id: "p5-workfromhome", d: "medium", q: "Every weekday, Mum gets to work in less than ten seconds. She has no car, bike or scooter, and she never runs. How?", a: "she works from home",
      alt: ["works from home","work from home","+from home","+work at home","+works at home","+home office","+home working","+downstairs","+upstairs","+next door","+above shop","+lives above","+lives at work","+wfh"],
      hints: ["She doesn't have to leave the house.","Her office is in the spare room."],
      why: "She works from home. Her whole journey is a few steps from the kitchen to her desk.", from: "new" },
    { id: "p5-wearingglasses", d: "medium", q: "Grandpa spent the whole morning hunting for his glasses. He searched every room and never found them, yet he could see perfectly well all morning. Why?", a: "he was wearing them",
      alt: ["wearing them","+wearing","+on his head","+on head","+on nose","+on face","+had them on","+on forehead","+wore them"],
      hints: ["They weren't in any of the rooms he searched.","Where do glasses go when you are using them?"],
      why: "He had them on all along. That is why he could see perfectly well while he searched for them.", from: "new" },
    { id: "p5-straightup", d: "medium", q: "How can you throw a ball as hard as you can and have it stop and come straight back to you, without it bouncing off anything or being tied to anything?", a: "throw it straight up",
      alt: ["straight up","upwards","up in the air","+straight up","+upward","+upwards","+up in air","+up into air","+into air","+in air","+vertical","+vertically","+into sky","+up high","+throw up","+sky high"],
      hints: ["Nothing has to hit it to make it come back.","Let gravity do the work."],
      why: "Throw it straight up. It slows down, stops at the top and falls right back to you. No wall or string needed.", from: "classic puzzle, reworded" },
    { id: "p5-overtakelast", d: "medium", q: "In a running race, you overtake the person in last place. What place are you in now?", a: "you can't overtake whoever is last",
      alt: ["impossible","you can not","+impossible","+not possible","+can not overtake","+can not pass","+can not be done","+no one behind","+nobody behind","+no such place","+trick question"],
      hints: ["Picture where you would have to be to overtake them.","Who is behind the person in last place?"],
      why: "You can't. To overtake the last runner you would have to be behind them, and then they wouldn't be last.", from: "classic puzzle, reworded" },
    { id: "p5-bigfamily", d: "hard", q: "Sally has eight brothers. Each of her brothers has six sisters. How many children are there in the family?", a: "fourteen",
      alt: ["14","fourteen children","14 children","fourteen kids","14 kids"],
      hints: ["Sally is one of her brothers' sisters.","Count each girl once, and Sally is a girl too."],
      why: "Each brother's six sisters include Sally herself, so there are six girls and eight boys: fourteen children.", from: "classic puzzle, reworded" },
    { id: "p5-queue", d: "hard", q: "Kate is tenth from the front of a queue and tenth from the back. How many people are in the queue?", a: "nineteen",
      alt: ["19","nineteen people","19 people"],
      hints: ["Kate gets counted from both ends.","Don't count Kate twice."],
      why: "There are nine people in front of Kate and nine behind her. Nine, plus nine, plus Kate makes nineteen.", from: "classic puzzle, reworded" },
    { id: "p5-fenceposts", d: "hard", q: "A straight fence is twenty metres long, with a post at each end and a post every metre in between. How many posts are there?", a: "twenty-one",
      alt: ["21","21 posts","twenty one posts"],
      hints: ["Picture a fence just one metre long. How many posts does it need?","There is always one more post than there are gaps."],
      why: "Twenty metres makes twenty one-metre gaps, and you need one more post than gaps to close off the far end: twenty-one.", from: "classic puzzle, reworded" },
    { id: "p5-newyeartwins", d: "hard", q: "Lily and her twin brother Leo were born on the same night, just a few minutes apart, but in different years. How?", a: "they were born either side of midnight",
      alt: ["+either side midnight","+before midnight","+after midnight","+across midnight","+around midnight","+new years eve","+new year","+december january","+one in december","+one in january"],
      hints: ["Think about one very special midnight.","One was born in December, the other in January."],
      why: "Leo was born just before midnight on 31 December and Lily just after, on 1 January. Minutes apart, but a year apart on paper.", from: "new" },
    { id: "p5-twocoins", d: "hard", q: "Two coins add up to 30 cents, and one of them is not a nickel. What are the two coins?", a: "a quarter and a nickel",
      alt: ["quarter and nickel","+quarter +nickel","+25 +5"],
      hints: ["Read it again: only ONE of them is not a nickel.","What about the other one?"],
      why: "One coin is a quarter, which is not a nickel. The other one is a nickel. The wording just makes you think neither can be.", from: "classic puzzle, reworded" },
    { id: "p5-callsheep", d: "medium", q: "A farmer has twenty sheep and ten goats. If you call a goat a sheep, how many sheep does the farmer have?", a: "twenty",
      alt: ["20","twenty sheep","20 sheep","+still twenty"],
      hints: ["Does calling a goat a sheep change the goat?","A goat with a new name is still a goat."],
      why: "Still twenty. Calling a goat a sheep doesn't turn it into one.", from: "classic puzzle, reworded" },
    { id: "p5-wife", d: "medium", q: "A man points at a woman and says, \"She is my mother-in-law's only child.\" Who is she?", a: "his wife",
      alt: ["wife","my wife","+wife","+missus","+spouse"],
      hints: ["Whose mother is his mother-in-law?","Who did he marry?"],
      why: "A man's mother-in-law is his wife's mother. If she has only one child, that child is his wife.", from: "classic puzzle, reworded" },
    { id: "p5-unclesister", d: "medium", q: "Your uncle has a sister, but she isn't your aunt. Who is she?", a: "your mother",
      alt: ["my mum","my mom","your mum","your mom","+your mother","+my mother","+your mum","+my mum","+your mom","+my mom","+my mummy","+my mommy"],
      hints: ["Which side of the family could your uncle be on?","Your uncle might be your mum's brother."],
      why: "If your uncle is your mum's brother, then his sister who isn't your aunt is your mum herself.", from: "classic puzzle, reworded" },
    { id: "p5-nora", d: "medium", q: "Nora's daughter has a little boy. Who is that boy's mother's mother?", a: "Nora",
      alt: ["+nora","his grandmother","+grandmother","+grandma","+granny","+nana"],
      hints: ["Who is the little boy's mother?","And whose daughter is she?"],
      why: "The boy's mother is Nora's daughter, and her mother is Nora herself.", from: "new" },
    { id: "p5-thirdsister", d: "medium", q: "Three sisters are in the sitting room. Anna is reading a book, and Kate is playing chess. What is the third sister doing?", a: "playing chess with Kate",
      alt: ["+playing chess","+chess with kate","+playing kate","+playing against kate","+kate opponent","+chess partner","+against kate","+with kate"],
      hints: ["Chess isn't a game you play on your own.","Who is sitting across the board from Kate?"],
      why: "Chess needs two players, and only three people are in the room. The third sister must be Kate's opponent.", from: "classic puzzle, reworded" },
    { id: "p5-scar", d: "hard", q: "I am a story with no words, written once and never rubbed out.\nThe one who wrote me left in a hurry and was gone within a week or two,\nbut I stayed behind to tell the tale.\nAsk me \"How did that happen?\" and someone else will answer.", a: "a scar",
      alt: ["scars","+scar"],
      hints: ["You might carry one from falling off a bike when you were small.","It is the mark a cut leaves on your skin after it heals."],
      why: "A scar tells the story of an old injury. The wound that wrote it healed and went away, but the scar stays, and when people ask about it, its owner tells the story.", from: "new" },
    { id: "p5-crater", d: "hard", q: "I am a footprint left by a visitor with no feet.\nIt came down from the sky in a single step and never took another.\nThe moon wears thousands of me on its face,\nand the faster my guest arrived, the wider I opened my arms.", a: "a crater",
      alt: ["craters","impact crater","meteor crater","meteorite crater","+crater"],
      hints: ["Look at the moon through binoculars and you will see lots of me.","I am the giant bowl a falling space rock punches into the ground."],
      why: "A crater is the 'footprint' of a meteorite, which has no feet and lands in one step. The moon is covered in craters, and the faster and bigger the impact, the wider the crater.", from: "new" },
    { id: "p5-delta", d: "hard", q: "I am an open hand at the end of a very long arm.\nThe arm has carried mountains, one grain at a time, for a thousand miles,\nand at the shore my fingers spread out to set them down.\nSeen from the sky, I look like roots growing into the sea.", a: "a river delta",
      alt: ["delta","deltas","river deltas","estuary","river mouth","mouth of a river","mouth of the river","+delta"],
      hints: ["You find me where a great river finally reaches the sea.","The Nile and the Mississippi both end in one of me. I share my name with a Greek letter."],
      why: "A delta forms where a river (the long arm) meets the sea and splits into many channels (the fingers), dropping the sand and mud it has carried down from the mountains. From above, it looks like a spread hand or roots.", from: "new" },
    { id: "p5-treerings", d: "hard", q: "I am a diary with one line for every year,\neach line a circle drawn around the last:\nfat in kind summers, thin in lean ones.\nMy writer never shows me to anyone while it stands;\nyou can only read me after it falls.", a: "tree rings",
      alt: ["tree ring","rings of a tree","rings in a tree","growth rings","annual rings","+tree ring","+growth ring","+annual ring"],
      hints: ["My writer has bark and leaves.","Count me on a tree stump to find out how old the tree was."],
      why: "A tree adds one ring a year, wide in good years and narrow in hard ones. You cannot see them while the tree stands, only on the stump once it has been cut down.", from: "new" },
    { id: "p5-dune", d: "hard", q: "I walk across the land without legs, a few steps every year.\nThe wind is my shepherd, and I am its flock of a billion grains.\nMy back is gentle and my face is steep,\nand I always turn that face away from the one who pushes me.", a: "a sand dune",
      alt: ["dune","dunes","sand dunes","+dune"],
      hints: ["You would find me in the Sahara, or at the back of a beach.","I am a hill made of sand."],
      why: "Sand dunes creep slowly across deserts as the wind blows grains over them. A dune has a gentle slope facing the wind and a steep face on the sheltered side.", from: "new" },
    { id: "p5-music", d: "hard", q: "I have no body, but I can move yours.\nI'm written down by people who hear me in their heads,\nI'm counted all the time but never added up,\nI rest without ever being tired,\nand I can fill a hall without taking up an inch of it.", a: "music",
      alt: ["a song","songs","melody","melodies","a tune","tunes","+music"],
      hints: ["You can't see me or touch me, but you might hum me.","Bands, orchestras and choirs make me."],
      why: "Music makes people dance, composers write down what they hear in their heads, players count the beats, the silent beats are called rests, and it fills a concert hall without taking up any room.", from: "new" },
    { id: "p5-word", d: "hard", q: "I'm smaller than a breath, yet I can be given, kept and broken.\nYou can mince me, eat me, or fight to have the last of me,\nand once I have left your lips, nobody can catch me again.\nThe dictionary is my family album.", a: "a word",
      alt: ["words","your word","spoken word","spoken words"],
      hints: ["You've used thousands of me today.","If you 'give me' you make a promise; if you 'eat me' you admit you were wrong."],
      why: "You give your word and keep it or break it; you can mince your words, eat your words, or have the last word. Once said, a word can't be taken back, and the dictionary lists them all.", from: "new" },
    { id: "p5-fear", d: "hard", q: "I live inside you, yet I'm always telling you to leave.\nI turn a coat on a hook into a stranger at night,\nI grow fat on every \"what if\",\nand I shrink each time you look me in the eye.", a: "fear",
      alt: ["fears","being scared","scared","afraid","being afraid","terror","worry","worries","anxiety","+fear"],
      hints: ["A scary film is made to give you me.","Brave people feel me too; they just do the thing anyway."],
      why: "Fear lives inside you but tells you to run, makes ordinary shapes in the dark look like intruders, feeds on worries, and gets smaller when you face it.", from: "new" },
    { id: "p5-childhood", d: "hard", q: "Everyone has owned me, but nobody gets to keep me.\nWhile you're inside me, you can't wait to get out;\nonce you've left, you'd give anything to visit,\nand the further you walk from me, the more golden I look.", a: "childhood",
      alt: ["your childhood","being a child","being a kid","being young","youth","+childhood"],
      hints: ["I begin the day you are born.","I'm over by the time you're grown up."],
      why: "Everyone has a childhood and nobody keeps it. Children can't wait to grow up, grown-ups wish they could go back, and childhood looks better the further away it gets.", from: "new" },
    { id: "p5-border", d: "hard", q: "I run for thousands of miles without taking a step.\nI cut mountains and rivers in two, yet birds fly over me without noticing.\nI'm drawn in ink but guarded day and night,\nand you can stand with one foot on each side of me.", a: "a border",
      alt: ["borders","boundary","boundaries","frontier","border line","national border","country border","state line","+border"],
      hints: ["You can see me on a map, but not from an aeroplane.","You cross me when you go from one country into another."],
      why: "A border between countries stretches for miles and splits the land, but birds can't see it: it is only drawn on maps, yet it is guarded. You can stand with one foot in each country.", from: "new" },
    { id: "p5-pride", d: "hard", q: "I can be swallowed but never chewed.\nI puff up your chest and lift up your chin.\nThe old saying says I come before a fall,\nand out on the savanna I'm a family of lions.", a: "pride",
      alt: ["proud","being proud","your pride","+pride"],
      hints: ["A parent feels me when their child wins a prize.","A group of lions is called this."],
      why: "You 'swallow your pride', it makes you stand tall, 'pride comes before a fall', and a group of lions is called a pride.", from: "new" },
    { id: "p5-deadline", d: "hard", q: "I'm a line nobody can see, drawn across a day.\nWhile I'm far away, nobody pays me any attention;\nas I come nearer, pencils speed up and lights stay on late,\nand the moment I'm crossed I vanish, though the trouble doesn't.", a: "a deadline",
      alt: ["deadlines","due date","+deadline"],
      hints: ["Teachers and bosses set me.","I am the time by which your homework must be handed in."],
      why: "A deadline is an invisible line on the calendar. People ignore it while it's far off and rush as it gets close, and once it has passed it's gone, but missing it can mean trouble.", from: "new" },
    { id: "p5-orbit", d: "hard", q: "I'm a racetrack with no ground, no start and no finishing line.\nThe moon has run me billions of times and never got any closer to home,\nand the only thing that keeps the runner on me\nis that it's falling all the time and always missing.", a: "an orbit",
      alt: ["orbits","orbiting","+orbit"],
      hints: ["Satellites and planets follow me.","The path one thing takes round and round another in space."],
      why: "An orbit is the path the moon (or a planet or satellite) travels round and round. An orbiting object is really falling the whole time, but it moves sideways so fast that it keeps missing the ground.", from: "new" },
    { id: "p5-constellation", d: "hard", q: "I'm a picture drawn with dots so far apart that light takes years to cross between them.\nThe dots have no idea they belong together,\nand from anywhere but here, my shape falls to pieces.\nSailors steered by me, and storytellers hung their heroes in me.", a: "a constellation",
      alt: ["constellations","star pattern","star patterns","asterism","+constellation"],
      hints: ["Look up on a clear, dark night.","Orion the Hunter and the Great Bear are two of me."],
      why: "A constellation is a pattern of stars. The stars are far apart and unrelated, and only look like a picture from Earth. Sailors navigated by them, and old stories named them after heroes.", from: "new" },
    { id: "p5-handshake", d: "hard", q: "I'm a contract with no paper and no ink,\nsigned by two people with the same kind of pen.\nI start meetings, end matches and seal bargains,\nand I can be firm, limp, or secret.", a: "a handshake",
      alt: ["handshakes","hand shake","shaking hands","shake hands","firm handshake"],
      hints: ["You do me with someone else, using your right hand.","Two people grip palms and move them up and down."],
      why: "A handshake seals a deal without any paperwork, made by two people using the same hand. It starts meetings, ends games and closes deals, and it can be firm, limp, or a secret club one.", from: "new" },
    { id: "p5-stranger", d: "hard", q: "Every friend you have was once me.\nYou pass hundreds of me every day without a word,\nand you were told never to take sweets from me,\nbut the moment we swap names, I disappear.", a: "a stranger",
      alt: ["strangers","+stranger"],
      hints: ["I'm not a thing. I'm a person.","I'm someone you've never met."],
      why: "Every friend started out as a stranger. You walk past strangers all the time, children are warned not to accept sweets from them, and once you introduce yourselves, they're no longer strangers.", from: "new" },
    { id: "p5-distance", d: "hard", q: "I grow with every step you take away and shrink with every step back.\nPeople who don't get along keep me,\nI'm measured in miles, in hours of driving, even in years of light,\nand they say I make the heart grow fonder.", a: "distance",
      alt: ["distances","absence","being apart","+distance"],
      hints: ["A map has a scale to help you work me out.","How far apart two places are."],
      why: "Distance grows as you walk away and shrinks as you come back. People 'keep their distance', it's measured in miles, hours or light years, and the saying goes that distance (or absence) makes the heart grow fonder.", from: "new" },
    { id: "p5-worldrecord", d: "hard", q: "I was made to be broken, and whoever breaks me gets a cheer.\nI'm the fastest, the highest, the longest, until the next time.\nA famous book is rewritten every year to keep up with me,\nand the one who breaks me makes a new me.", a: "a world record",
      alt: ["world records","record","records","+world record"],
      hints: ["Athletes chase me at the Olympics.","The best result anyone has ever achieved, written down in Guinness."],
      why: "Records are 'made to be broken', and breaking one gets a cheer. A world record is the best ever until someone beats it, Guinness World Records comes out every year, and whoever breaks the record sets a new one.", from: "new" },
    { id: "p5-contrail", d: "hard", q: "I'm a cloud drawn with a ruler.\nA silver pencil sketches me across the blue, faster than any bird,\nand the wind rubs me out a little at a time.", a: "a vapour trail",
      alt: ["contrail","contrails","vapour trails","vapor trail","vapor trails","jet trail","condensation trail","plane trail","airplane trail","aeroplane trail","+vapour trail","+vapor trail","+contrail","+jet trail","+plane trail"],
      hints: ["Look up on a clear day when a jet passes far overhead.","The long white line an aeroplane leaves across the sky."],
      why: "A vapour trail (contrail) is a straight line of cloud left by a high-flying jet, the 'silver pencil'. Over time the wind spreads it out until it disappears.", from: "new" },
    { id: "p5-forgiveness", d: "hard", q: "I'm a key that opens a cell,\nand the prisoner who walks free is the one who turned me.\nI'm hardest to give to the people who need me most,\nand an apology can knock on my door, but it can't open it for me.", a: "forgiveness",
      alt: ["forgiving","forgive","to forgive","mercy","pardon","+forgiveness","+forgive"],
      hints: ["I'm something you give to someone who has hurt you.","When someone says sorry, you can offer me back."],
      why: "Forgiving someone frees you from carrying the anger, so the one who forgives is the one set free. It is hardest to forgive those who hurt us most, and an apology can ask for forgiveness but can't force it.", from: "new" },
    { id: "p5-hindsight", d: "hard", q: "I'm the sharpest eye you'll ever own,\nbut I can only look over your shoulder.\nI see every wrong turn perfectly, just after it's too late to take the right one,\nand any eye doctor would give me a perfect score.", a: "hindsight",
      alt: ["hind sight","looking back","+hindsight"],
      hints: ["I only arrive after something has already happened.","People say I'm 20/20."],
      why: "Hindsight is seeing clearly after the event, looking back. It shows you every mistake once it's too late, and the saying goes that 'hindsight is 20/20', which is perfect eyesight.", from: "new" },
    { id: "p5-geode", d: "hard", q: "I'm a lumpy brown potato that nobody looks at twice.\nI was hollow before I was finished,\nand for a million years a slow rain built a cathedral inside me.\nCrack my skull and you'll be the first ever to see it lit.", a: "a geode",
      alt: ["geodes","crystal geode","amethyst geode","+geode"],
      hints: ["Despite how I look, I'm made of stone.","Break me open and I am lined with sparkling crystals."],
      why: "A geode looks like a dull, round rock, but it formed around a hollow, and mineral-rich water slowly grew crystals inside it. Whoever cracks it open is the first to see them.", from: "new" },
    { id: "p5-drought", d: "hard", q: "I'm a thief who never needs to open a door.\nI drink the rivers without a mouth and crack the fields without a hammer,\nI turn green to gold and gold to bare earth,\nand I'm only ever caught when the clouds come back.", a: "a drought",
      alt: ["droughts","dry spell","drouth","+drought"],
      hints: ["Farmers fear me more than almost anything.","A long time with no rain."],
      why: "A drought takes water without breaking in. Rivers dry up, the ground cracks, green fields turn yellow then bare, and it only ends when the rain returns.", from: "new" },
    { id: "p5-dust", d: "hard", q: "I fall without rain and settle without a home.\nYou chase me off with a cloth on Saturday, and I'm back by Sunday.\nI was once mountains, and stars, and the skin on your arms,\nand if you write your name in me, I'll keep it until I'm swept away.", a: "dust",
      alt: ["dusts","household dust","dust bunnies","dust bunny","+dust"],
      hints: ["A sunbeam through a window shows me floating in the air.","I gather on shelves and under the bed."],
      why: "Dust drifts down and settles everywhere, and comes back however often you clean. It is made of worn-down rock, specks from space and tiny flakes of skin, and you can write in a layer of it with your finger.", from: "new" },
    { id: "p5-rust", d: "medium", q: "I have no teeth, yet I eat iron.\nI have no fire, yet I wear the colour of flame.\nThe rain wakes me, and patience is my only tool:\ngive me a hundred years and I'll gobble up a ship.", a: "rust",
      alt: ["rusting","corrosion","oxidation","+rust"],
      hints: ["You find me on old cars, gates and bikes left out in the rain.","I am the orange-brown crust that grows on wet iron."],
      why: "Rust slowly eats away iron and steel. It is orange-red like flame, it forms when iron gets wet, and given time it can destroy even a ship.", from: "new" },
    { id: "p5-path", d: "medium", q: "The more feet that tread on me, the clearer I become;\nleave me alone for one summer and the grass swallows me.\nI never move an inch, yet I can take you there and bring you back.", a: "a path",
      alt: ["paths","footpath","footpaths","pathway","trail","trails","desire path","+path"],
      hints: ["You often find me running across a park or through the woods.","I am a narrow way worn by walkers."],
      why: "A path gets clearer the more people walk on it and grows over when nobody does. It never moves, but it leads you somewhere and back again.", from: "new" },
    { id: "p5-sleep", d: "medium", q: "I'm a thief who calls every night and takes a third of your life,\nand you thank me for it in the morning.\nThe harder you chase me, the faster I run,\nbut stop trying, and I'll carry you off without a sound.", a: "sleep",
      alt: ["sleeping","slumber"],
      hints: ["Counting sheep is meant to help you catch me.","You do me in bed every night."],
      why: "Sleep takes about a third of your life and you feel better for it. Trying hard to fall asleep keeps it away, and when you relax it takes you without your noticing.", from: "new" },
    { id: "p5-hunger", d: "medium", q: "I'm the best sauce in any kitchen, though no cook can bottle me.\nI growl without a throat and gnaw without teeth.\nFeed me and I die; starve me and I grow.", a: "hunger",
      alt: ["appetite","starving","+hunger"],
      hints: ["You feel me just before lunch.","Your tummy rumbles when I visit."],
      why: "An old saying calls hunger 'the best sauce' because it makes any food taste good. It makes your stomach growl and gnaw, eating makes it go away, and going without food makes it worse.", from: "new" },
    { id: "p5-kiss", d: "medium", q: "I can be blown across a room without any wind,\nplanted without a garden, and stolen without a thief.\nIn the old stories I turn frogs into princes\nand wake princesses who have slept for a hundred years.", a: "a kiss",
      alt: ["kisses","kissing","peck","smooch","+kiss"],
      hints: ["You might get one from a grandparent when you say goodnight.","You give it with your lips."],
      why: "You can blow a kiss, plant one on someone's cheek, or steal one. In fairy tales a kiss turns the frog back into a prince and wakes Sleeping Beauty.", from: "new" },
    { id: "p5-blush", d: "medium", q: "I'm a fire that gives no heat, lit by a word or a glance.\nI rise up your cheeks like a tide, and you can't hold me back,\nand the harder you try to hide me, the brighter I glow.", a: "a blush",
      alt: ["blushes","blushing","going red","turning red","red cheeks","rosy cheeks","embarrassment","+blush"],
      hints: ["A compliment or an embarrassing moment can set me off.","Your face goes pink or red."],
      why: "A blush is a rush of colour to the cheeks, set off by a comment or a look. You can't stop it, and trying to hide it only makes it worse.", from: "new" },
    { id: "p5-fever", d: "medium", q: "I'm a fire your body lights on purpose, to burn out uninvited guests.\nI'm read under your tongue,\nand I make you shiver with cold while you're burning up.", a: "a fever",
      alt: ["fevers","temperature","high temperature","+fever"],
      hints: ["A parent might feel your forehead to check for me.","A thermometer tells you if you have one."],
      why: "A fever is the body raising its temperature to fight germs. It is measured with a thermometer under the tongue, and it can make you feel cold and shivery even though you are hot.", from: "new" },
    { id: "p5-debt", d: "medium", q: "I'm made of money you haven't got.\nLeft alone, I grow fat on nothing but time;\nevery payment makes me thinner,\nand I follow you from house to house until you settle me.", a: "a debt",
      alt: ["debts","loan","loans","iou","money owed","overdraft","mortgage","+debt"],
      hints: ["Banks and credit cards can give you me.","What you owe someone."],
      why: "A debt is money you owe, not money you have. Interest makes it grow over time, each payment shrinks it, and it stays with you until you pay it off.", from: "new" },
    { id: "p5-antlers", d: "medium", q: "I'm a bare tree that grows on a head.\nI sprout in spring in a velvet coat,\nI'm polished for fighting by autumn,\nand in winter I fall like leaves, to grow back bigger next year.", a: "antlers",
      alt: ["antler","deer antlers","stag antlers","+antler"],
      hints: ["Look at a stag.","Deer grow me and drop me every year."],
      why: "Antlers branch like a bare tree on a deer's head. They grow in spring covered in soft 'velvet', are rubbed clean for autumn fights, and drop off in winter before growing back bigger.", from: "new" },
    { id: "p5-bruise", d: "medium", q: "I'm a painting made without a brush; a bump against the table was my artist.\nI start as a storm cloud, turn the green of a pond,\nfade to the yellow of old paper, then leave without a trace.\nPress me, and I complain.", a: "a bruise",
      alt: ["bruises","black and blue","+bruise"],
      hints: ["You might get one when you bang your knee.","I am black and blue at first."],
      why: "A bruise appears after a knock. It starts dark purple-blue, turns green, then yellow, then fades away, and it hurts when pressed.", from: "new" },
    { id: "p5-pollen", d: "medium", q: "I'm a love letter one flower sends to another.\nThe flower can't walk to the post, so it pays the bees in sweets to carry me,\nor throws me on the wind and hopes.\nEach spring I make half the town sneeze.", a: "pollen",
      alt: ["pollen grain","pollen grains","+pollen"],
      hints: ["I am a fine yellow powder found inside flowers.","Hay fever is caused by me."],
      why: "Pollen carries a flower's message to another flower so it can make seeds. Bees carry it in return for nectar, or the wind blows it, and it gives people hay fever in spring.", from: "new" },
    { id: "p5-wink", d: "medium", q: "I'm a secret told with half a face.\nI'm over faster than you can say so, but I say a great deal,\nand I can mean \"only joking\" or \"you and I both know\"\nwithout a single word.", a: "a wink",
      alt: ["winks","winking"],
      hints: ["You do me with one eye.","Close one eye quickly, then open it."],
      why: "A wink is a quick close of one eye ('half a face'). It's over in a moment but carries a message, like 'just kidding' or 'our secret'.", from: "new" },
    { id: "p5-shrug", d: "medium", q: "I'm the shortest answer there is, and I don't use the mouth.\nI lift two loads and set them down together,\nand without a sound I can say\n\"I don't know\", \"who cares?\" or \"whatever you like\".", a: "a shrug",
      alt: ["shrugs","shrugging","shrug your shoulders","+shrug"],
      hints: ["You might do me when someone asks a question you can't answer.","You raise both shoulders and drop them."],
      why: "A shrug lifts both shoulders (the two loads) and drops them, saying 'I don't know' or 'I don't mind' without words.", from: "new" },
    { id: "p5-argument", d: "medium", q: "It takes two to make me, though one can start me.\nI get hot without any fire,\nI'm made of words thrown like stones,\nand someone can win me while everybody loses.", a: "an argument",
      alt: ["arguments","arguing","quarrel","quarrels","fight","row","disagreement","squabble","+argument"],
      hints: ["Brothers and sisters have me over whose turn it is.","A row or a quarrel."],
      why: "An argument needs two people, gets heated, is made of harsh words, and even when someone wins it, everyone ends up feeling worse.", from: "new" },
    { id: "p5-itch", d: "medium", q: "I'm the smallest tyrant in the world:\nI give a single order, and your hand obeys at once.\nThe more you do as I say, the louder I shout,\nand I like to hide in the middle of your back, where you can't reach.", a: "an itch",
      alt: ["itches","itching","itchy","+itch"],
      hints: ["A mosquito bite leaves me behind.","I make you want to scratch."],
      why: "An itch makes you scratch at once, scratching often makes it worse, and the most annoying ones are where you can't reach.", from: "new" },
    { id: "p5-money", d: "medium", q: "I talk, though I have no mouth.\nI burn holes in pockets, though I have no fire.\nI don't grow on trees, though I'm often made from them,\nand I can't buy the things you'll want most.", a: "money",
      alt: ["cash","dollars"],
      hints: ["You keep me in a wallet or a piggy bank.","Coins and notes."],
      why: "'Money talks', it 'burns a hole in your pocket', it 'doesn't grow on trees' though paper notes are made from them, and it 'can't buy happiness'.", from: "new" }
]); })(typeof window !== 'undefined' ? window : this);
